def cards(rows):return '<div class="cards">'+''.join('<article><h3>'+a+'</h3><p>'+b+'</p></article>' for a,b in rows)+'</div>'
def note(s):return '<aside><b>CHECK BEFORE YOU CONTINUE</b><p>'+s+'</p></aside>'
def shot(key,caption='Actual Hagzz interface. Local demonstration records; not customer results.'):
 return f'<figure><img src="assets/{key}.png"><figcaption>{caption}</figcaption></figure>'
def steps(rows):return '<ol class="steps">'+''.join(f'<li><span>{i+1:02}</span><div>{v}</div></li>' for i,v in enumerate(rows))+'</ol>'
def workflow(rows):return '<div class="workflow">'+''.join(f'<div><span>{i+1:02}</span><b>{r}</b></div>' for i,r in enumerate(rows))+'</div>'
