CSS=(R/'english.css').read_text()
def render(items,stem):
 out=['<!doctype html><html lang="en" dir="ltr"><meta charset="utf-8"><title>Hagzz | Academy Management Experience — Qatar</title><style>'+CSS+'</style><body>']
 for i,p in enumerate(items):
  out.append(f'<section id="p{i+1}" class="{p["kind"]}"><header><img src="assets/hagzz.svg"><span>QATAR / ACADEMIES</span><small>MANAGEMENT EXPERIENCE</small></header><div class="title"><div class="eyebrow">HAGZZ / ACADEMY GUIDE</div><h1>{p["title"]}</h1><p>{p["sub"]}</p></div><main>{p["body"]}</main><footer><span>HAGZZ • ENGLISH EDITION / OCTOBER 2026</span><span>{i+1:02} — {len(items):02}</span></footer></section>')
 out.append('</body></html>');(R/(stem+'.html')).write_text(''.join(out));(R/(stem+'-pages.json')).write_text(json.dumps([{k:v for k,v in p.items() if k!='body'} for p in items],indent=2));print(stem,len(items))
